var v = String(source.getVariable()).split(',');
var idx = parseInt(v[0]) || 0;
var tabs = ['小说', '听书', '漫画', '短剧'];
var tab = tabs[idx] || '小说';
var channels = ['男频', '女频'];
var ch = channels[parseInt(v[3]) || 0] || '男频';
var url = 'https://fq.taijiwang.top/api/discover/style?tab=' + encodeURIComponent(tab) + '&source_type=' + encodeURIComponent(ch);
