var TypeNames = ["小说", "听书", "漫画", "短剧"];
var TypeValues = [3, 2, 8, 11];

function TYPE() {
    var v = String(this.source.getVariable()).split(",");
    var idx = parseInt(v[0]) || 0;
    return TypeValues[idx] !== undefined ? TypeValues[idx] : 3;
}

function TAB() {
    var v = String(this.source.getVariable()).split(",");
    var idx = parseInt(v[0]) || 0;
    var tabs = ["%E5%B0%8F%E8%AF%B4", "%E5%90%AC%E4%B9%A6", "%E6%BC%AB%E7%94%BB", "%E7%9F%AD%E5%89%A7"];
    return tabs[idx] !== undefined ? tabs[idx] : "%E5%B0%8F%E8%AF%B4";
}

function CMTOFF() {
    var v = String(this.source.getVariable()).split(",");
    return v[1] == 'off';
}

